-- Compare Survev equipment geometry generated by PINNED official TS.
local Camera=require("src.survev.camera")
local Player=require("src.survev.player_renderer")
local fixture=assert(loadfile(assert(arg[1])))()
local cam=Camera.new()
cam.m_pos={x=320,y=330}
cam.m_screenWidth,cam.m_screenHeight=960,640
local r=Player.new()
local checked=0
local function near(a,b,name)
    assert(type(a)=="number" and type(b)=="number",name.." non-number")
    assert(math.abs(a-b)<1e-7,
        string.format("%s expected %.12g got %.12g",name,b,a))
    checked=checked+1
end
for idx,item in ipairs(fixture.cases) do
    local commands=assert(r:commands(item.player,cam,"main"))
    local mapping={}
    for _,cmd in ipairs(commands) do mapping[cmd.name]=cmd end
    for name,source in pairs(item.expected) do
        local got=mapping[name]
        assert(got,"Survev equipment part missing: "..name.." at case "..idx)
        for _,field in ipairs({
            "x","y","rotation","scaleX","scaleY","anchorX","anchorY"
        }) do
            near(got[field],source[field],name.."."..field.." case "..idx)
        end
    end
end
assert(checked>=90,"insufficient weapon/gear parity coverage")
print("Original Survev equipment geometry parity:",checked,
    "numeric values across",#fixture.cases,"loadouts")
